472	/// The stories a drafting reply gives: each's title, prompt, and mode, in
473	/// order. Chain where its mode isn't one known.
474	pub fn parse_drafts(reply: &str) -> Result<Vec<(String, String, SendMode)>> {
475	    let start = reply.find('{').context("the reply held no stories")?;
476	    let end = reply.rfind('}').context("the reply held no stories")?;
477	    let parsed: DraftReply = serde_json::from_str(&reply[start..=end])
478	        .context("the reply's stories couldn't be read")?;
479	    let stories: Vec<_> = parsed
480	        .stories
481	        .into_iter()
482	        .filter(|story| !story.title.trim().is_empty() || !story.prompt.trim().is_empty())
483	        .map(|story| {
484	            let title = if story.title.trim().is_empty() {
485	                story
486	                    .prompt
487	                    .lines()
488	                    .next()
489	                    .unwrap_or_default()
490	                    .trim()
491	                    .to_string()
492	            } else {
493	                story.title.trim().to_string()
494	            };
495	            let mode = mode_of_slug(&story.mode).unwrap_or(SendMode::Both);
496	            (title, story.prompt.trim().to_string(), mode)
497	        })
498	        .collect();
499	    anyhow::ensure!(!stories.is_empty(), "the reply held no stories");
500	    Ok(stories)
501	}
