662	    fn new_story_at(
663	        &mut self,
664	        section: Section,
665	        at: Option<usize>,
666	        window: &mut Window,
667	        cx: &mut Context<Self>,
668	    ) {
669	        let section = if section == Section::Done {
670	            Section::Backlog
671	        } else {
672	            section
673	        };
674	        self.close_story(window, cx);
675	        let story = Story::new(String::new(), String::new(), last_mode(), &self.project_dir);
676	        let name = story.name.clone();
677	        let stories = &mut self.sections[section_ix(section)];
678	        let at = at.unwrap_or(stories.len()).min(stories.len());
679	        stories.insert(at, story);
680	        self.save_story_named(&name, cx);
681	        self.save_order(cx);
682	        self.open_story(&name, window, cx);
683	    }
