685	    /// Adds a story of `mode` holding `prompt` at the end of the Backlog.
686	    pub fn add_story(
687	        &mut self,
688	        title: String,
689	        prompt: String,
690	        mode: SendMode,
691	        cx: &mut Context<Self>,
692	    ) {
693	        let story = Story::new(title, prompt, mode, &self.project_dir);
694	        let name = story.name.clone();
695	        self.sections[1].push(story);
696	        self.save_story_named(&name, cx);
697	        self.save_order(cx);
698	        cx.notify();
