701	    /// Opens the story named so beneath its row, closing any other.
702	    fn open_story(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
703	        if self.open.as_ref().is_some_and(|open| open.name == name) {
704	            return;
705	        }
706	        self.close_story(window, cx);
707	        let Some(story) = self.story_mut(name) else {
708	            return;
709	        };
710	        // A draft opened is a story like any other.
711	        let was_draft = std::mem::take(&mut story.draft);
712	        let (title_text, prompt_text) = (story.title.clone(), story.prompt.clone());
713	        let title = cx.new(|cx| {
714	            InputState::new(window, cx)
715	                .placeholder("Story title")
716	                .default_value(title_text)
717	        });
718	        let prompt = cx.new(|cx| {
719	            EditorState::new(window, cx)
720	                .language(piton_syntax::LANGUAGE_NAME)
721	                .line_number(false)
722	                .folding(false)
723	                .soft_wrap(true)
724	                .scroll_beyond_last_line(Some(0))
725	                .cursor_surrounding_lines(Some(0))
726	                .placeholder("Prompt… (the title is sent where there's none)")
727	                .default_value(prompt_text)
728	        });
729	        let completion = cx.new(|cx| CompletionMenu::new(prompt.clone(), window, cx));
730	        let provider = (self.hooks.completions)(cx);
731	        completion.update(cx, |menu, cx| menu.set_provider(provider, cx));
732	        let story_name = name.to_string();
733	        let subscriptions = vec![
734	            cx.subscribe_in(&title, window, {
735	                let name = story_name.clone();
736	                move |this, input, event: &InputEvent, window, cx| match event {
737	                    InputEvent::Change => {
738	                        let value = input.read(cx).value().to_string();
739	                        if let Some(story) = this.story_mut(&name) {
740	                            story.title = value;
741	                        }
742	                        this.save_order(cx);
743	                        cx.notify();
744	                    }
745	                    InputEvent::PressEnter { .. } => this.title_entered(&name, window, cx),
746	                    _ => {}
747	                }
748	            }),
749	            cx.subscribe_in(&prompt, window, {
750	                let name = story_name.clone();
751	                move |this, editor, event: &InputEvent, window, cx| {
752	                    if matches!(event, InputEvent::Change) {
753	                        let value = editor.read(cx).value().to_string();
754	                        if let Some(story) = this.story_mut(&name) {
755	                            story.prompt = value;
756	                        }
757	                        this.save_story_named(&name, cx);
758	                        if let Some(open) = &this.open {
759	                            open.completion
760	                                .update(cx, |menu, cx| menu.on_edit(window, cx));
761	                        }
762	                    }
763	                    cx.notify();
764	                }
765	            }),
766	        ];
767	        title.update(cx, |input, cx| input.focus(window, cx));
768	        self.open = Some(OpenStory {
769	            name: story_name.clone(),
770	            title,
771	            prompt,
772	            completion,
773	            fit: GrowToFit::new(PROMPT_MAX_ROWS),
774	            _subscriptions: subscriptions,
775	        });
776	        if was_draft {
777	            self.save_order(cx);
778	        }
779	        cx.notify();
780	    }
