782	    /// Closes the open story; one left with neither title nor prompt is
783	    /// removed.
784	    fn close_story(&mut self, window: &mut Window, cx: &mut Context<Self>) {
785	        let Some(open) = self.open.take() else {
786	            return;
787	        };
788	        let empty = self
789	            .find(&open.name)
790	            .map(|(section, ix)| &self.sections[section_ix(section)][ix])
791	            .is_some_and(|story| story.title.trim().is_empty() && story.prompt.trim().is_empty());
792	        if empty {
793	            self.delete(&open.name, cx);
794	        }
795	        self.focus.focus(window, cx);
796	        cx.notify();
797	    }
