799	    /// Enter in an open story's title: it is kept, and another starts
800	    /// beneath it, so a list can be written down without the mouse.
801	    fn title_entered(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
802	        let Some((section, ix)) = self.find(name) else {
803	            return;
804	        };
805	        if self.sections[section_ix(section)][ix]
806	            .title
807	            .trim()
808	            .is_empty()
809	        {
810	            return;
811	        }
812	        self.new_story_at(section, Some(ix + 1), window, cx);
813	    }
