815	    /// Escape: closes an open completion menu, else the open story, which,
816	    /// left empty, goes.
817	    fn escape(&mut self, window: &mut Window, cx: &mut Context<Self>) {
818	        if let Some(open) = &self.open {
819	            if open.completion.read(cx).is_open() {
820	                open.completion.update(cx, |menu, cx| menu.hide(cx));
821	                return;
822	            }
823	            self.close_story(window, cx);
824	        } else if self.drafting.as_ref().is_some_and(|draft| !draft.running) {
825	            self.drafting = None;
826	            cx.notify();
827	        }
828	    }
829	
830	    /// Ctrl/Cmd+N: a story in the section of the one open, else the
831	    /// Backlog.
832	    fn new_story_here(&mut self, window: &mut Window, cx: &mut Context<Self>) {
833	        let section = self
834	            .open
835	            .as_ref()
836	            .and_then(|open| self.find(&open.name))
837	            .map_or(Section::Backlog, |(section, _)| section);
838	        self.new_story(section, window, cx);
839	    }
