841	    fn delete(&mut self, name: &str, cx: &mut Context<Self>) {
842	        let Some((section, ix)) = self.find(name) else {
843	            return;
844	        };
845	        self.sections[section_ix(section)].remove(ix);
846	        if self.open.as_ref().is_some_and(|open| open.name == name) {
847	            self.open = None;
848	        }
