// --- The view -----------------------------------------------------------------

/// The story open beneath its row, and its editors.
struct OpenStory {
    name: String,
    title: Entity<InputState>,
    prompt: Entity<EditorState>,
    completion: Entity<CompletionMenu>,
    fit: GrowToFit,
    _subscriptions: Vec<Subscription>,
}

/// The drafting panel, as the PlanningScope's drafting says: the request,
/// the run while it goes, and how it ended.
struct DraftPanel {
    input: Entity<TextareaState>,
    /// While the run goes: when it started.
    running: Option<Instant>,
    /// A run that failed: what was reported.
    error: Option<String>,
    details_open: bool,
    /// The last run proposed nothing.
    proposed_nothing: bool,
    _run: Option<Task<()>>,
}

/// A story's row dragged.
#[derive(Clone)]
struct StoryDrag {
    name: String,
    title: SharedString,
    mode: SendMode,
}

impl Render for StoryDrag {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let theme = cx.theme();
        h_flex()
            .gap_2()
            .px_3()
            .h(ROW_HEIGHT)
            .rounded(theme.radius)
            .bg(crate::theme::color(crate::theme::palette(cx).raised))
            .shadow_md()
            .text_sm()
            .child(mode_pill_label(self.mode, cx))
            .child(self.title.clone())
    }
}

pub struct Planning {
    project_dir: PathBuf,
    /// Next sprint, Backlog, Done, and the proposals, in order.
    sections: [Vec<Story>; 4],
    open: Option<OpenStory>,
    done_expanded: bool,
    drafting: Option<DraftPanel>,
    /// The mode picker open: the story's, and the mode highlighted.
    mode_menu: Option<(String, usize)>,
    /// The story asking to be deleted.
    confirm_delete: Option<String>,
    hooks: PlanningHooks,
    focus: FocusHandle,
    /// Each row's focus, by its story's name.
    row_focus: std::collections::HashMap<String, FocusHandle>,
    /// The Done section's toggle's focus.
    done_focus: FocusHandle,
    /// While a row is dragged: the gap it would land in.
    gap: Rc<Cell<Option<(Section, usize)>>>,
    /// Ticks once a second while a story's task runs, for its time.
    _tick: Option<Task<()>>,
}

impl EventEmitter<()> for Planning {}

impl Focusable for Planning {
    fn focus_handle(&self, _: &App) -> FocusHandle {
        self.focus.clone()
    }
}

impl Planning {
    pub fn new(project_dir: PathBuf, hooks: PlanningHooks, cx: &mut Context<Self>) -> Self {
        let sections = load(&project_dir);
        let this = Self {
            project_dir,
            sections,
            open: None,
            done_expanded: false,
            drafting: None,
            mode_menu: None,
            confirm_delete: None,
            hooks,
            focus: cx.focus_handle(),
            row_focus: Default::default(),
            done_focus: cx.focus_handle().tab_stop(true),
            gap: Rc::default(),
            _tick: None,
        };
        this.publish(cx);
        this
    }

    /// The stories of `section`.
    #[cfg(test)]
    pub fn stories(&self, section: Section) -> &[Story] {
        &self.sections[section_ix(section)]
    }

    /// How many stories wait in Next sprint to be sent, for the ribbon.
    pub fn pending(&self) -> SprintPending {
        SprintPending(self.unsent())
    }

    /// Says how many stories wait in Next sprint to be sent, for the ribbon.
    fn publish(&self, cx: &mut App) {
        cx.set_global(self.pending());
    }

    fn unsent(&self) -> usize {
        self.sections[0]
            .iter()
            .filter(|story| story.task.is_none())
            .count()
    }

    fn find(&self, name: &str) -> Option<(Section, usize)> {
        SECTIONS.into_iter().find_map(|section| {
            self.sections[section_ix(section)]
                .iter()
                .position(|story| story.name == name)
                .map(|ix| (section, ix))
        })
    }

    fn story(&self, name: &str) -> Option<&Story> {
        let (section, ix) = self.find(name)?;
        self.sections[section_ix(section)].get(ix)
    }

    fn story_mut(&mut self, name: &str) -> Option<&mut Story> {
        let (section, ix) = self.find(name)?;
        self.sections[section_ix(section)].get_mut(ix)
    }

    /// Saves the order in the background.
    fn save_order(&self, cx: &mut Context<Self>) {
        let text = order_of(&self.sections);
        let dir = self.project_dir.clone();
        cx.background_spawn(async move {
            if let Err(err) = save_order_text(&dir, &text) {
                eprintln!("could not save the plan: {err:#}");
            }
        })
        .detach();
        self.publish(cx);
    }

    /// Saves the story named so in the background.
    fn save_story_named(&self, name: &str, cx: &mut Context<Self>) {
        let Some(story) = self.story(name) else {
            return;
        };
        let (dir, name, source) = (
            self.project_dir.clone(),
            story.name.clone(),
            story.anchor.source(&story.prompt),
        );
        cx.background_spawn(async move {
            if let Err(err) = save_story(&dir, &name, &source) {
                eprintln!("could not save the story: {err:#}");
            }
        })
        .detach();
    }

    /// Adds a story at the end of `section`, open, its title focused, in
    /// the mode last picked.
    pub fn new_story(&mut self, section: Section, window: &mut Window, cx: &mut Context<Self>) {
        self.new_story_at(section, None, window, cx);
    }

    fn new_story_at(
        &mut self,
        section: Section,
        at: Option<usize>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let section = match section {
            Section::Next | Section::Proposed => section,
            Section::Backlog | Section::Done => Section::Backlog,
        };
        self.close_story(window, cx);
        let story = Story::new(String::new(), String::new(), last_mode(), &self.project_dir);
        let name = story.name.clone();
        let stories = &mut self.sections[section_ix(section)];
        let at = at.unwrap_or(stories.len()).min(stories.len());
        stories.insert(at, story);
        self.save_story_named(&name, cx);
        self.save_order(cx);
        self.open_story(&name, window, cx);
    }

    /// Adds a story of `mode` holding `prompt` at the end of the Backlog.
    pub fn add_story(
        &mut self,
        title: String,
        prompt: String,
        mode: SendMode,
        cx: &mut Context<Self>,
    ) {
        let story = Story::new(title, prompt, mode, &self.project_dir);
        let name = story.name.clone();
        self.sections[1].push(story);
        self.save_story_named(&name, cx);
        self.save_order(cx);
        cx.notify();
    }

    /// Opens the story named so beneath its row, closing any other.
    fn open_story(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        if self.open.as_ref().is_some_and(|open| open.name == name) {
            return;
        }
        self.close_story(window, cx);
        // A draft opened is a story like any other; a proposal stays one
        // until it is added.
        let proposal = self
            .find(name)
            .is_some_and(|(section, _)| section == Section::Proposed);
        let Some(story) = self.story_mut(name) else {
            return;
        };
        let was_draft = !proposal && std::mem::take(&mut story.draft);
        let (title_text, prompt_text) = (story.title.clone(), story.prompt.clone());
        let title = cx.new(|cx| {
            InputState::new(window, cx)
                .placeholder("Story title")
                .default_value(title_text)
        });
        let prompt = cx.new(|cx| {
            EditorState::new(window, cx)
                .language(piton_syntax::LANGUAGE_NAME)
                .line_number(false)
                .folding(false)
                .soft_wrap(true)
                .scroll_beyond_last_line(Some(0))
                .cursor_surrounding_lines(Some(0))
                .placeholder("Prompt… (the title is sent where there's none)")
                .default_value(prompt_text)
        });
        let completion = cx.new(|cx| CompletionMenu::new(prompt.clone(), window, cx));
        let provider = (self.hooks.completions)(cx);
        completion.update(cx, |menu, cx| menu.set_provider(provider, cx));
        let story_name = name.to_string();
        let subscriptions = vec![
            cx.subscribe_in(&title, window, {
                let name = story_name.clone();
                move |this, input, event: &InputEvent, window, cx| match event {
                    InputEvent::Change => {
                        let value = input.read(cx).value().to_string();
                        if let Some(story) = this.story_mut(&name) {
                            story.title = value;
                        }
                        this.save_order(cx);
                        cx.notify();
                    }
                    InputEvent::PressEnter { .. } => this.title_entered(&name, window, cx),
                    _ => {}
                }
            }),
            cx.subscribe_in(&prompt, window, {
                let name = story_name.clone();
                move |this, editor, event: &InputEvent, window, cx| {
                    if matches!(event, InputEvent::Change) {
                        let value = editor.read(cx).value().to_string();
                        if let Some(story) = this.story_mut(&name) {
                            story.prompt = value;
                        }
                        this.save_story_named(&name, cx);
                        if let Some(open) = &this.open {
                            open.completion
                                .update(cx, |menu, cx| menu.on_edit(window, cx));
                        }
                    }
                    cx.notify();
                }
            }),
        ];
        title.update(cx, |input, cx| input.focus(window, cx));
        self.open = Some(OpenStory {
            name: story_name,
            title,
            prompt,
            completion,
            fit: GrowToFit::new(PROMPT_MAX_ROWS),
            _subscriptions: subscriptions,
        });
        if was_draft {
            self.save_order(cx);
        }
        cx.notify();
    }

    /// Closes the open story, its row focused again; one left with neither
    /// title nor prompt is removed.
    fn close_story(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(open) = self.open.take() else {
            return;
        };
        let empty = self.story(&open.name).is_some_and(|story| {
            story.title.trim().is_empty() && story.prompt.trim().is_empty()
        });
        if empty {
            self.delete(&open.name, cx);
            self.focus.focus(window, cx);
        } else {
            self.focus_row(&open.name, window, cx);
        }
        cx.notify();
    }

    fn toggle_story(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        if self.open.as_ref().is_some_and(|open| open.name == name) {
            self.close_story(window, cx);
        } else {
            self.open_story(name, window, cx);
        }
    }

    /// Enter in an open story's title: it is kept, and another starts
    /// beneath it, so a list can be written down without the mouse.
    fn title_entered(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        let Some((section, ix)) = self.find(name) else {
            return;
        };
        if self.sections[section_ix(section)][ix]
            .title
            .trim()
            .is_empty()
        {
            return;
        }
        self.new_story_at(section, Some(ix + 1), window, cx);
    }

    /// Escape: closes what is open, one layer at a time: the mode picker or
    /// a confirmation, the completions, the open story, then the drafting
    /// panel. Whether there was anything to close.
    fn escape(&mut self, window: &mut Window, cx: &mut Context<Self>) -> bool {
        if self.mode_menu.take().is_some() || self.confirm_delete.take().is_some() {
            cx.notify();
            return true;
        }
        if let Some(open) = &self.open {
            if open.completion.read(cx).is_open() {
                open.completion.update(cx, |menu, cx| menu.hide(cx));
                return true;
            }
            self.close_story(window, cx);
            return true;
        }
        if self
            .drafting
            .as_ref()
            .is_some_and(|draft| draft.running.is_none())
            && self.sections[3].is_empty()
        {
            self.drafting = None;
            self.focus.focus(window, cx);
            cx.notify();
            return true;
        }
        false
    }

    /// Ctrl/Cmd+N: a story in the section of the one open or focused, else
    /// the Backlog.
    fn new_story_here(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let section = self
            .open
            .as_ref()
            .map(|open| open.name.clone())
            .or_else(|| self.focused_story(window))
            .and_then(|name| self.find(&name))
            .map_or(Section::Backlog, |(section, _)| section);
        self.new_story(section, window, cx);
    }

    fn delete(&mut self, name: &str, cx: &mut Context<Self>) {
        let Some((section, ix)) = self.find(name) else {
            return;
        };
        self.sections[section_ix(section)].remove(ix);
        self.row_focus.remove(name);
        if self.open.as_ref().is_some_and(|open| open.name == name) {
            self.open = None;
        }
        if self.confirm_delete.as_deref() == Some(name) {
            self.confirm_delete = None;
        }
        let file = story_file(&self.project_dir, name);
        cx.background_spawn(async move {
            std::fs::remove_file(file).ok();
        })
        .detach();
        self.save_order(cx);
        cx.notify();
    }

    /// Asks, in its row, to delete the story named so.
    fn ask_delete(&mut self, name: &str, cx: &mut Context<Self>) {
        self.mode_menu = None;
        self.confirm_delete = Some(name.to_string());
        cx.notify();
    }

    /// Deletes the story asking to be, the focus going to the row beside.
    fn confirm_delete(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(name) = self.confirm_delete.take() else {
            return;
        };
        let next = self
            .row_after(&name, 1)
            .or_else(|| self.row_after(&name, -1));
        self.delete(&name, cx);
        match next {
            Some(next) => self.focus_row(&next, window, cx),
            None => self.focus.focus(window, cx),
        }
    }

    fn duplicate(&mut self, name: &str, cx: &mut Context<Self>) {
        let Some((section, ix)) = self.find(name) else {
            return;
        };
        let copy = self.sections[section_ix(section)][ix].duplicate();
        let copy_name = copy.name.clone();
        self.sections[section_ix(section)].insert(ix + 1, copy);
        self.save_story_named(&copy_name, cx);
        self.save_order(cx);
        cx.notify();
    }

    /// Moves the story named so to place `to` of `section`, counted as the
    /// section is before it is taken out.
    fn move_story(&mut self, name: &str, section: Section, to: usize, cx: &mut Context<Self>) {
        let Some((from_section, from)) = self.find(name) else {
            return;
        };
        let to = if from_section == section && to > from {
            to - 1
        } else {
            to
        };
        let story = self.sections[section_ix(from_section)].remove(from);
        let stories = &mut self.sections[section_ix(section)];
        stories.insert(to.min(stories.len()), story);
        self.save_order(cx);
        cx.notify();
    }

    pub(crate) fn move_to(&mut self, name: &str, section: Section, cx: &mut Context<Self>) {
        let end = self.sections[section_ix(section)].len();
        self.move_story(name, section, end, cx);
    }

    /// Alt+Up or Alt+Down: the story moves one place, and past the end of
    /// its section into the next, between Next sprint and the Backlog, as
    /// dragging does; a proposal or a story done moves only among its own.
    pub(crate) fn shift_story(&mut self, name: &str, up: bool, cx: &mut Context<Self>) {
        let Some((section, ix)) = self.find(name) else {
            return;
        };
        let len = self.sections[section_ix(section)].len();
        match (section, up) {
            (_, true) if ix > 0 => self.move_story(name, section, ix - 1, cx),
            (_, false) if ix + 1 < len => self.move_story(name, section, ix + 2, cx),
            (Section::Backlog, true) => self.move_to(name, Section::Next, cx),
            (Section::Next, false) => self.move_story(name, Section::Backlog, 0, cx),
            _ => {}
        }
    }

    fn set_mode(&mut self, name: &str, mode: SendMode, cx: &mut Context<Self>) {
        if let Ok(mut last) = LAST_MODE.lock() {
            *last = Some(mode);
        }
        if let Some(story) = self.story_mut(name) {
            story.anchor.mode = Some(mode);
        }
        self.mode_menu = None;
        self.save_story_named(name, cx);
        cx.notify();
    }

    /// Opens the mode picker of the story named so, its mode highlighted.
    fn open_mode_menu(&mut self, name: &str, cx: &mut Context<Self>) {
        let Some(story) = self.story(name) else {
            return;
        };
        let at = SendMode::ALL
            .iter()
            .position(|mode| *mode == story.mode())
            .unwrap_or(0);
        self.confirm_delete = None;
        self.mode_menu = Some((name.to_string(), at));
        cx.notify();
    }

    fn change(
        &mut self,
        name: &str,
        change: impl FnOnce(&mut HiddenAnchor),
        cx: &mut Context<Self>,
    ) {
        if let Some(story) = self.story_mut(name) {
            change(&mut story.anchor);
        }
        self.save_story_named(name, cx);
        cx.notify();
    }

    /// Attaches files picked to the story named so.
    fn attach(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        let picked = cx.prompt_for_paths(PathPromptOptions {
            files: true,
            directories: false,
            multiple: true,
            prompt: Some("Attach".into()),
        });
        let (name, project_dir) = (name.to_string(), self.project_dir.clone());
        cx.spawn_in(window, async move |this, cx| {
            let Ok(Ok(Some(paths))) = picked.await else {
                return;
            };
            let saved = cx
                .background_spawn(async move {
                    let (mut images, mut files) = (Vec::new(), Vec::new());
                    for path in paths {
                        match attached_file::load(&path) {
                            Ok(attached_file::Loaded::Image(image)) => images.push(image),
                            Ok(attached_file::Loaded::File(file)) => files.push(file),
                            Err(_) => {}
                        }
                    }
                    let images = attached_image::save_all(&images, &project_dir)?;
                    let files = attached_file::save_all(&files, &project_dir)?;
                    anyhow::Ok((images, files))
                })
                .await;
            this.update(cx, |this, cx| match saved {
                Ok((images, files)) => this.change(
                    &name,
                    |anchor| {
                        anchor.attached_images.extend(images);
                        anchor.attached_files.extend(files);
                    },
                    cx,
                ),
                Err(err) => eprintln!("could not attach the files: {err:#}"),
            })
            .ok();
        })
        .detach();
    }

    /// How the story stands, once sent, and how long its task has run while
    /// it runs.
    fn status(&self, story: &Story, cx: &App) -> Option<(StoryState, Option<Duration>)> {
        let task = story.task.as_deref()?;
        Some((self.hooks.state)(task, cx).unwrap_or((StoryState::Queued, None)))
    }

    fn state(&self, story: &Story, cx: &App) -> Option<StoryState> {
        self.status(story, cx).map(|(state, _)| state)
    }

    /// Sends the stories named so, in order, as one block.
    fn send_named(&mut self, names: &[String], window: &mut Window, cx: &mut Context<Self>) {
        let mut sends = Vec::new();
        for name in names {
            let project_dir = self.project_dir.clone();
            let Some(story) = self.story_mut(name) else {
                continue;
            };
            if story.text().trim().is_empty() {
                continue;
            }
            let task = crate::prompt_title::name_for(&project_dir, &story.title);
            story.task = Some(task.clone());
            story.draft = false;
            sends.push(StorySend {
                name: task,
                text: story.text(),
                mode: story.mode(),
                attached: story.anchor.attached(),
                sliced: story.anchor.sliced,
                model: story.anchor.model.clone(),
                effort: story.anchor.effort.clone(),
            });
        }
        if sends.is_empty() {
            return;
        }
        self.save_order(cx);
        (self.hooks.send)(sends, window, cx);
        cx.notify();
    }

    /// Sends the story named so alone; a proposal or a story done is never
    /// sent from here.
    fn send_story(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        if self
            .find(name)
            .is_some_and(|(section, _)| matches!(section, Section::Proposed | Section::Done))
        {
            return;
        }
        self.send_named(&[name.to_string()], window, cx);
    }

    /// Sends every story of Next sprint not yet sent, in order, as one
    /// block.
    pub fn send_sprint(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let names: Vec<String> = self.sections[0]
            .iter()
            .filter(|story| story.task.is_none())
            .map(|story| story.name.clone())
            .collect();
        self.send_named(&names, window, cx);
    }

    /// Whether every story of the sprint was sent and has ended.
    fn sprint_ended(&self, cx: &App) -> bool {
        !self.sections[0].is_empty()
            && self.sections[0]
                .iter()
                .all(|story| self.state(story, cx).is_some_and(StoryState::ended))
    }

    /// Closes the sprint: the stories done go to Done; those that failed or
    /// were cancelled stay, to be sent again.
    fn close_sprint(&mut self, cx: &mut Context<Self>) {
        let stories = std::mem::take(&mut self.sections[0]);
        for mut story in stories {
            if self.state(&story, cx) == Some(StoryState::Done) {
                self.sections[2].push(story);
            } else {
                story.task = None;
                self.sections[0].push(story);
            }
        }
        self.save_order(cx);
        cx.notify();
    }

    fn resume(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        if let Some(task) = self.story(name).and_then(|story| story.task.clone()) {
            (self.hooks.resume)(&task, window, cx);
        }
    }

    /// Opens the drafting panel beneath the Backlog's heading; focused, it
    /// takes the request.
    fn open_draft_panel(&mut self, focus: bool, window: &mut Window, cx: &mut Context<Self>) {
        if self.drafting.is_none() {
            let input = cx.new(|cx| {
                TextareaState::new(window, cx)
                    .auto_grow(2, DRAFT_MAX_ROWS)
                    .placeholder("In a sentence or a paragraph…")
            });
            self.drafting = Some(DraftPanel {
                input,
                running: None,
                error: None,
                details_open: false,
                proposed_nothing: false,
                _run: None,
            });
        }
        if focus && let Some(drafting) = &self.drafting {
            drafting
                .input
                .update(cx, |input, cx| input.focus(window, cx));
        }
        cx.notify();
    }

    /// Asks the harness to break what the panel's request says into
    /// stories, proposed in the panel to be added.
    fn draft(&mut self, cx: &mut Context<Self>) {
        let Some(drafting) = &mut self.drafting else {
            return;
        };
        let wanted = drafting.input.read(cx).value().to_string();
        if wanted.trim().is_empty() || drafting.running.is_some() {
            return;
        }
        drafting.running = Some(Instant::now());
        drafting.error = None;
        drafting.details_open = false;
        drafting.proposed_nothing = false;
        let (project_dir, ask) = (self.project_dir.clone(), self.hooks.draft);
        let run = cx.spawn(async move |this, cx| {
            let reply = cx
                .background_spawn(async move {
                    ask(&project_dir, &wanted).and_then(|reply| parse_drafts(&reply))
                })
                .await;
            this.update(cx, |this, cx| this.drafted(reply, cx)).ok();
        });
        drafting._run = Some(run);
        cx.notify();
    }

    /// Stops the run: whatever it would have proposed is never shown.
    fn stop_draft(&mut self, cx: &mut Context<Self>) {
        if let Some(drafting) = &mut self.drafting {
            drafting._run = None;
            drafting.running = None;
        }
        cx.notify();
    }

    fn drafted(
        &mut self,
        reply: Result<Vec<(String, String, SendMode)>>,
        cx: &mut Context<Self>,
    ) {
        let Some(drafting) = &mut self.drafting else {
            return;
        };
        drafting.running = None;
        drafting._run = None;
        match reply {
            Ok(stories) if stories.is_empty() => drafting.proposed_nothing = true,
            Ok(stories) => {
                for (title, prompt, mode) in stories {
                    let mut story = Story::new(title, prompt, mode, &self.project_dir);
                    story.draft = true;
                    let name = story.name.clone();
                    self.sections[3].push(story);
                    self.save_story_named(&name, cx);
                }
                self.save_order(cx);
            }
            Err(err) => drafting.error = Some(format!("{err:#}")),
        }
        cx.notify();
    }

    fn toggle_proposal(&mut self, name: &str, cx: &mut Context<Self>) {
        if self
            .find(name)
            .is_some_and(|(section, _)| section == Section::Proposed)
            && let Some(story) = self.story_mut(name)
        {
            story.checked = !story.checked;
            self.save_order(cx);
            cx.notify();
        }
    }

    /// Adds the proposals ticked to the Backlog, in order, as drafts, lets
    /// the rest go, and closes the panel.
    pub(crate) fn add_proposals(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        for story in std::mem::take(&mut self.sections[3]) {
            if story.checked {
                self.sections[1].push(story);
            } else {
                std::fs::remove_file(story_file(&self.project_dir, &story.name)).ok();
            }
        }
        self.close_panel(window, cx);
    }

    /// Lets every proposal go, and closes the panel.
    fn discard_proposals(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        for story in std::mem::take(&mut self.sections[3]) {
            std::fs::remove_file(story_file(&self.project_dir, &story.name)).ok();
        }
        self.close_panel(window, cx);
    }

    fn close_panel(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self
            .open
            .as_ref()
            .is_some_and(|open| self.find(&open.name).is_none())
        {
            self.open = None;
        }
        self.drafting = None;
        self.save_order(cx);
        self.focus.focus(window, cx);
        cx.notify();
    }

    /// The rows in the order they are shown, by their stories' names.
    fn shown_rows(&self) -> Vec<String> {
        let mut shown = vec![Section::Next];
        if self.drafting.is_some() || !self.sections[3].is_empty() {
            shown.push(Section::Proposed);
        }
        shown.push(Section::Backlog);
        if self.done_expanded {
            shown.push(Section::Done);
        }
        shown
            .into_iter()
            .flat_map(|section| self.sections[section_ix(section)].iter())
            .map(|story| story.name.clone())
            .collect()
    }

    /// The row `step` rows on from the story named so.
    fn row_after(&self, name: &str, step: isize) -> Option<String> {
        let rows = self.shown_rows();
        let at = rows.iter().position(|row| row == name)? as isize + step;
        rows.get(usize::try_from(at).ok()?).cloned()
    }

    fn row_focus(&mut self, name: &str, cx: &mut App) -> FocusHandle {
        self.row_focus
            .entry(name.to_string())
            .or_insert_with(|| cx.focus_handle().tab_stop(true))
            .clone()
    }

    fn focus_row(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        let handle = self.row_focus(name, cx);
        handle.focus(window, cx);
        cx.notify();
    }

    /// The story whose row has the focus.
    fn focused_story(&self, window: &Window) -> Option<String> {
        self.row_focus
            .iter()
            .find(|(_, handle)| handle.is_focused(window))
            .map(|(name, _)| name.clone())
    }

    /// Up or Down on a focused row: the mode picker's highlight moves while
    /// it is open, else the focus moves to the row beside.
    fn step_rows(&mut self, step: isize, window: &mut Window, cx: &mut Context<Self>) {
        if let Some((_, at)) = &mut self.mode_menu {
            let count = SendMode::ALL.len() as isize;
            *at = (*at as isize + step).rem_euclid(count) as usize;
            cx.notify();
            return;
        }
        let Some(name) = self.focused_story(window) else {
            return;
        };
        if let Some(next) = self.row_after(&name, step) {
            self.focus_row(&next, window, cx);
        }
    }

    /// Enter on a focused row: picks the highlighted mode while the picker
    /// is open, deletes a story whose delete was asked for, else opens or
    /// closes the story.
    fn enter_row(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if let Some((name, at)) = self.mode_menu.clone() {
            self.set_mode(&name, SendMode::ALL[at], cx);
            return;
        }
        if self.confirm_delete.is_some() {
            return self.confirm_delete(window, cx);
        }
        if let Some(name) = self.focused_story(window) {
            self.toggle_story(&name, window, cx);
        }
    }

    /// Ticks once a second while a story's task runs, so its time counts.
    fn keep_ticking(&mut self, cx: &mut Context<Self>) {
        if self._tick.is_some() {
            return;
        }
        self._tick = Some(cx.spawn(async move |this, cx| {
            loop {
                cx.background_executor()
                    .timer(Duration::from_secs(1))
                    .await;
                let running = this
                    .update(cx, |this, cx| {
                        let running = this.any_running(cx)
                            || this
                                .drafting
                                .as_ref()
                                .is_some_and(|drafting| drafting.running.is_some());
                        if running {
                            cx.notify();
                        } else {
                            this._tick = None;
                        }
                        running
                    })
                    .unwrap_or(false);
                if !running {
                    break;
                }
            }
        }));
    }

    fn any_running(&self, cx: &App) -> bool {
        self.sections[..3]
            .iter()
            .flatten()
            .any(|story| self.state(story, cx) == Some(StoryState::Running))
    }
}

/// Every section, in the order they are looked through.
const SECTIONS: [Section; 4] = [
    Section::Next,
    Section::Backlog,
    Section::Done,
    Section::Proposed,
];

fn section_ix(section: Section) -> usize {
    match section {
        Section::Next => 0,
        Section::Backlog => 1,
        Section::Done => 2,
        Section::Proposed => 3,
    }
}

/// How wide a row's grip is.
const GRIP_WIDTH: Pixels = px(16.);

/// How wide a row's mode pill is.
const PILL_WIDTH: Pixels = px(72.);

/// How wide a row's status and time are.
const STATUS_WIDTH: Pixels = px(96.);

/// How tall a section's heading is.
const HEADING_HEIGHT: Pixels = px(32.);

/// How far apart rows are.
const ROW_GAP: Pixels = px(2.);

/// How far a section's first row is beneath its heading.
const HEADING_GAP: Pixels = px(8.);

/// A mode's pill: its label, small, in its colour.
fn mode_pill_label(mode: SendMode, cx: &App) -> Div {
    let color = chat_input::mode_color(mode, cx);
    div()
        .flex_none()
        .px_1p5()
        .rounded(px(4.))
        .text_xs()
        .font_medium()
        .text_color(color)
        .bg(color.opacity(0.14))
        .child(mode_label(mode))
}

/// A sent story's status, as a task's is shown in the message list: its
/// coloured label, with a spinner and its time while it runs, and a pause
/// icon while paused.
fn status_label(state: StoryState, elapsed: Option<Duration>, cx: &App) -> AnyElement {
    use crate::theme::Hue;
    let hue = match state {
        StoryState::Queued => Hue::Grey,
        StoryState::Running => Hue::Amber,
        StoryState::Done => Hue::Green,
        StoryState::Failed => Hue::Red,
        StoryState::Cancelled => Hue::Orange,
        // The theme's warning colour, as a paused task's.
        StoryState::Paused => Hue::Amber,
    };
    let muted = cx.theme().muted_foreground;
    let tag = crate::theme::tag(hue, cx).text_xs().child(
        h_flex()
            .gap_1()
            .items_center()
            .when(state == StoryState::Paused, |tag| {
                tag.child(Icon::new(IconName::Pause).xsmall())
            })
            .child(state.label()),
    );
    h_flex()
        .gap_1()
        .justify_end()
        .items_center()
        .when(state == StoryState::Running, |row| {
            row.child(Spinner::new().xsmall())
        })
        .child(tag)
        .children(
            elapsed
                .filter(|_| state == StoryState::Running)
                .map(|elapsed| {
                    div()
                        .text_xs()
                        .text_color(muted)
                        .font_features(crate::subagents::tabular_figures())
                        .child(crate::subagents::format_elapsed(elapsed))
                }),
        )
        .into_any_element()
}

/// `element`, taking the clicks on what it holds for itself, so the row
/// it sits in never sees them.
fn own_clicks(element: Div) -> Div {
    element.on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
}

/// An empty state: one muted line, centred, saying what is missing and what
/// to do.
fn empty_line(text: String, muted: Hsla) -> Div {
    div()
        .w_full()
        .h(ROW_HEIGHT)
        .flex()
        .items_center()
        .justify_center()
        .text_sm()
        .text_color(muted)
        .child(text)
}

/// A loading state: a spinner and a short muted label, where the result
/// will appear.
fn loading_line(label: String, muted: Hsla) -> Div {
    h_flex()
        .h(ROW_HEIGHT)
        .px_3()
        .gap_2()
        .items_center()
        .text_sm()
        .text_color(muted)
        .child(Spinner::new().xsmall())
        .child(label)
}

impl Planning {
    fn render_heading(&self, section: Section, cx: &mut Context<Self>) -> AnyElement {
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let count = self.sections[section_ix(section)].len();
        let paused = self.sections[section_ix(section)]
            .iter()
            .filter(|story| self.state(story, cx) == Some(StoryState::Paused))
            .count();
        let warning = crate::theme::Hue::Amber.of(crate::theme::palette(cx));
        let mut actions: Vec<AnyElement> = Vec::new();
        match section {
            Section::Next => {
                if self.sprint_ended(cx) {
                    actions.push(
                        Button::new("planning-close-sprint")
                            .ghost()
                            .small()
                            .label("Close sprint")
                            .tooltip(
                                "Move the stories done to Done, leaving any that failed to send again",
                            )
                            .on_click(cx.listener(|this, _, _, cx| this.close_sprint(cx)))
                            .into_any_element(),
                    );
                }
                let unsent = self.unsent();
                actions.push(
                    Button::new("planning-send-sprint")
                        .primary()
                        .small()
                        .icon(IconName::Send)
                        .label("Send sprint")
                        .disabled(unsent == 0)
                        .tooltip(match unsent {
                            0 => "Nothing in Next sprint is waiting to be sent".to_string(),
                            1 => format!("Send the one story waiting ({MOD}Shift+Enter)"),
                            n => format!(
                                "Send the {n} stories waiting, in order ({MOD}Shift+Enter)"
                            ),
                        })
                        .on_click(
                            cx.listener(|this, _, window, cx| this.send_sprint(window, cx)),
                        )
                        .into_any_element(),
                );
            }
            Section::Backlog => {
                actions.push(
                    Button::new("planning-draft-stories")
                        .ghost()
                        .small()
                        .icon(IconName::Sparkles)
                        .label("Draft stories")
                        .tooltip("Describe what you want, and have the harness propose stories")
                        .on_click(cx.listener(|this, _, window, cx| {
                            this.open_draft_panel(true, window, cx)
                        }))
                        .into_any_element(),
                );
            }
            Section::Done | Section::Proposed => {}
        }
        let name = div().text_sm().font_semibold().child(section.label());
        let heading = if section == Section::Done {
            // Collapsed until opened, from its heading.
            gpui_kit::TestSupportExt::test_support(
                h_flex()
                    .id("planning-done-toggle")
                    .track_focus(&self.done_focus)
                    .gap_2()
                    .px_1()
                    .items_center()
                    .rounded(theme.radius)
                    .border_1()
                    .border_color(gpui_kit::transparent_black())
                    .focus(|toggle| toggle.border_color(theme.ring))
                    .cursor_pointer()
                    .text_color(muted)
                    .aria_label(if self.done_expanded {
                        "Hide the stories done"
                    } else {
                        "Show the stories done"
                    })
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.done_expanded = !this.done_expanded;
                        cx.notify();
                    }))
                    .on_action(cx.listener(|this, _: &ToggleStory, _, cx| {
                        this.done_expanded = !this.done_expanded;
                        cx.notify();
                    }))
                    .key_context(ROW_CONTEXT)
                    .child(
                        Icon::new(if self.done_expanded {
                            IconName::ChevronDown
                        } else {
                            IconName::ChevronRight
                        })
                        .xsmall(),
                    )
                    .child(name),
            )
            .into_any_element()
        } else {
            name.into_any_element()
        };
        h_flex()
            .w_full()
            .h(HEADING_HEIGHT)
            .flex_none()
            .gap_2()
            .items_center()
            .child(heading)
            .child(div().text_xs().text_color(muted).child(count.to_string()))
            .when(paused > 0, |row| {
                row.child(
                    div()
                        .text_xs()
                        .text_color(warning)
                        .child(format!("{paused} paused")),
                )
            })
            .child(div().flex_1())
            .children(actions)
            .into_any_element()
    }

    fn render_section(
        &mut self,
        section: Section,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let heading = self.render_heading(section, cx);
        let mut column = v_flex()
            .w_full()
            .gap(ROW_GAP)
            .child(div().pb(HEADING_GAP - ROW_GAP).child(heading));
        if section == Section::Backlog && (self.drafting.is_some() || !self.sections[3].is_empty())
        {
            // Proposals kept from before come back in their panel.
            if self.drafting.is_none() {
                self.open_draft_panel(false, window, cx);
            }
            column = column.child(self.render_draft_panel(window, cx));
        }
        if section == Section::Done && !self.done_expanded {
            return column.into_any_element();
        }
        let gap = self.gap.get();
        let count = self.sections[section_ix(section)].len();
        if count == 0 {
            column = column.child(
                self.drop_zone(
                    section,
                    0,
                    div().id(SharedString::from(format!(
                        "planning-empty-{}",
                        section.key()
                    ))),
                    cx,
                )
                .child(empty_line(section.empty(), muted)),
            );
        }
        for ix in 0..count {
            let name = self.sections[section_ix(section)][ix].name.clone();
            let open = self.open.as_ref().is_some_and(|open| open.name == name);
            let row = self.render_row(section, ix, open, gap, window, cx);
            column = column.child(row);
            if open {
                column = column.child(self.render_open(&name, window, cx));
            }
        }
        if !matches!(section, Section::Done | Section::Proposed) {
            let new_story = self
                .drop_zone(
                    section,
                    count,
                    h_flex()
                        .id(SharedString::from(format!(
                            "planning-new-story-{}",
                            section.key()
                        )))
                        .h(px(28.))
                        .px_3()
                        .gap_2()
                        .items_center()
                        .rounded(theme.radius)
                        .cursor_pointer()
                        .text_sm()
                        .text_color(muted)
                        .aria_label("New story")
                        .tooltip(move |window, cx| {
                            gpui_kit::component::tooltip::Tooltip::new(format!(
                                "Add a story here ({MOD}N)"
                            ))
                            .build(window, cx)
                        })
                        .hover(|row| row.bg(theme.list_hover)),
                    cx,
                )
                .on_click(
                    cx.listener(move |this, _, window, cx| this.new_story(section, window, cx)),
                )
                .child(Icon::new(IconName::Plus).xsmall())
                .child("New story");
            column = column.child(gpui_kit::TestSupportExt::test_support(new_story));
        }
        column.into_any_element()
    }

    /// `element` as somewhere a dragged story can be dropped, at place `at`
    /// of `section`.
    fn drop_zone(
        &self,
        section: Section,
        at: usize,
        element: Stateful<Div>,
        cx: &mut Context<Self>,
    ) -> Stateful<Div> {
        let gap = self.gap.clone();
        let shown = gap.get() == Some((section, at));
        element
            .relative()
            .on_drag_move(move |event: &DragMoveEvent<StoryDrag>, window, _| {
                if event.bounds.contains(&event.event.position) && gap.get() != Some((section, at))
                {
                    gap.set(Some((section, at)));
                    window.refresh();
                }
            })
            .on_drop(cx.listener(move |this, drag: &StoryDrag, _, cx| {
                this.gap.set(None);
                this.move_story(&drag.name, section, at, cx);
            }))
            .when(shown, |this| {
                this.child(crate::prompt_mode::drop_indicator(false, false, cx))
            })
    }

    fn render_mode_menu(
        &self,
        name: &str,
        mode: SendMode,
        highlighted: usize,
        cx: &mut Context<Self>,
    ) -> impl IntoElement + use<> {
        let theme = cx.theme().clone();
        let items = SendMode::ALL
            .into_iter()
            .enumerate()
            .map(|(at, choice)| {
                let name = name.to_string();
                h_flex()
                    .id(SharedString::from(format!(
                        "planning-mode-{name}-{}",
                        mode_label(choice)
                    )))
                    .px_2()
                    .h(px(26.))
                    .gap_2()
                    .items_center()
                    .rounded(theme.radius)
                    .cursor_pointer()
                    .when(at == highlighted, |item| item.bg(theme.list_active))
                    .hover(|item| item.bg(theme.list_hover))
                    .aria_label(mode_label(choice))
                    .on_click(cx.listener(move |this, _, _, cx| this.set_mode(&name, choice, cx)))
                    .child(div().w(px(14.)).children(
                        (choice == mode).then(|| Icon::new(IconName::Check).xsmall()),
                    ))
                    .child(mode_pill_label(choice, cx))
            })
            .collect::<Vec<_>>();
        let menu = v_flex()
            .id(SharedString::from(format!("planning-mode-menu-{name}")))
            .mt(px(26.))
            .w(px(140.))
            .p_1()
            .rounded(theme.radius)
            .border_1()
            .border_color(theme.border)
            .bg(theme.popover)
            .shadow_md()
            .occlude()
            .on_mouse_down_out(cx.listener(|this, _, _, cx| {
                this.mode_menu = None;
                cx.notify();
            }))
            .children(items);
        deferred(
            anchored()
                .snap_to_window()
                .child(gpui_kit::TestSupportExt::test_support(menu)),
        )
        .with_priority(2)
    }

    fn render_row(
        &mut self,
        section: Section,
        ix: usize,
        open: bool,
        gap: Option<(Section, usize)>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let story = &self.sections[section_ix(section)][ix];
        let name = story.name.clone();
        let mode = story.mode();
        let status = self.status(story, cx);
        let (draft, checked, attached) = (story.draft, story.checked, story.has_attachments());
        let task = story.task.clone();
        let untitled = story.title.trim().is_empty();
        let title: SharedString = if untitled {
            "Untitled".into()
        } else {
            story.title.clone().into()
        };
        let len = self.sections[section_ix(section)].len();
        let focus = self.row_focus(&name, cx);
        let focused = focus.is_focused(window);
        let group = SharedString::from(format!("planning-row-{name}"));
        let proposal = section == Section::Proposed;
        let paused = status.is_some_and(|(state, _)| state == StoryState::Paused);
        let confirming = self.confirm_delete.as_deref() == Some(name.as_str());

        // The mode picker: its pill, and beneath it, while open, the modes.
        let mode_menu = self
            .mode_menu
            .as_ref()
            .filter(|(of, _)| *of == name)
            .map(|(_, at)| *at)
            .map(|highlighted| self.render_mode_menu(&name, mode, highlighted, cx));
        let mode_picker = {
            let name = name.clone();
            Button::new(SharedString::from(format!("planning-mode-{name}")))
                .ghost()
                .xsmall()
                .child(mode_pill_label(mode, cx))
                .tooltip("How it will be sent (M)")
                .on_click(cx.listener(move |this, _, _, cx| {
                    if this.mode_menu.as_ref().is_some_and(|(of, _)| *of == name) {
                        this.mode_menu = None;
                        cx.notify();
                    } else {
                        this.open_mode_menu(&name, cx);
                    }
                }))
        };
        let send = {
            let name = name.clone();
            Button::new(SharedString::from(format!("planning-send-{name}")))
                .ghost()
                .xsmall()
                .icon(IconName::Send)
                .label("Send")
                .tooltip(format!("Send this story on its own ({MOD}Enter)"))
                .on_click(
                    cx.listener(move |this, _, window, cx| this.send_story(&name, window, cx)),
                )
        };
        let resume = paused.then(|| {
            let name = name.clone();
            Button::new(SharedString::from(format!("planning-resume-{name}")))
                .ghost()
                .xsmall()
                .icon(IconName::Play)
                .label("Resume")
                .tooltip("Resume this story's task where it left off")
                .on_click(cx.listener(move |this, _, window, cx| this.resume(&name, window, cx)))
        });
        let this = cx.entity().downgrade();
        let menu_name = name.clone();
        let menu = Button::new(SharedString::from(format!("planning-menu-{name}")))
            .ghost()
            .xsmall()
            .icon(IconName::Ellipsis)
            .tooltip("More")
            .dropdown_menu_with_anchor(gpui_kit::Anchor::TopRight, move |menu, _, _| {
                let item = |label: &'static str, act: fn(&mut Planning, &str, &mut Context<Planning>)| {
                    let (this, name) = (this.clone(), menu_name.clone());
                    PopupMenuItem::new(label).on_click(move |_, _, cx| {
                        this.update(cx, |this, cx| act(this, &name, cx)).ok();
                    })
                };
                let menu = match section {
                    Section::Next => menu.item(item("Move to backlog", |this, name, cx| {
                        this.move_story(name, Section::Backlog, 0, cx)
                    })),
                    Section::Backlog | Section::Done => {
                        menu.item(item("Move to next sprint", |this, name, cx| {
                            this.move_to(name, Section::Next, cx)
                        }))
                    }
                    Section::Proposed => menu,
                };
                menu.item(item("Duplicate", |this, name, cx| this.duplicate(name, cx)))
                    .separator()
                    .item(item("Delete…", |this, name, cx| this.ask_delete(name, cx)))
            });
        let confirm = confirming.then(|| {
            h_flex()
                .gap_1()
                .items_center()
                .child(
                    div()
                        .text_xs()
                        .text_color(theme.danger)
                        .child("Delete this story?"),
                )
                .child(
                    Button::new(SharedString::from(format!("planning-delete-{name}")))
                        .danger()
                        .xsmall()
                        .label("Delete")
                        .tooltip("Delete it for good (Enter)")
                        .on_click(
                            cx.listener(|this, _, window, cx| this.confirm_delete(window, cx)),
                        ),
                )
                .child(
                    Button::new(SharedString::from(format!("planning-keep-{name}")))
                        .ghost()
                        .xsmall()
                        .label("Cancel")
                        .tooltip("Keep it (Escape)")
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.confirm_delete = None;
                            cx.notify();
                        })),
                )
        });
        let checkbox = proposal.then(|| {
            let name = name.clone();
            Checkbox::new(SharedString::from(format!("planning-propose-{name}")))
                .checked(checked)
                .on_click(
                    cx.listener(move |this, _: &bool, _, cx| this.toggle_proposal(&name, cx)),
                )
        });

        let dragging = cx.has_active_drag();
        let drag = StoryDrag {
            name: name.clone(),
            title: title.clone(),
            mode,
        };
        let click_name = name.clone();
        let row = h_flex()
            .id(SharedString::from(format!("planning-story-{name}")))
            .key_context(ROW_CONTEXT)
            .track_focus(&focus)
            .aria_label(title.clone())
            .group(group.clone())
            .relative()
            .w_full()
            .h(ROW_HEIGHT)
            .flex_none()
            .px_3()
            .gap_2()
            .items_center()
            .rounded(theme.radius)
            // The focus ring, on the row the keys work on.
            .border_1()
            .border_color(if focused {
                theme.ring
            } else {
                gpui_kit::transparent_black()
            })
            .cursor_pointer()
            .when(open, |row| row.bg(theme.list_active))
            .when(!open, |row| row.hover(|row| row.bg(theme.list_hover)))
            .on_click(cx.listener(move |this, _, window, cx| {
                // A story sent opens its task; any other opens, or closes.
                this.focus_row(&click_name, window, cx);
                if let Some(task) = task.as_deref().filter(|_| !open) {
                    (this.hooks.open_task)(task, window, cx);
                } else {
                    this.toggle_story(&click_name, window, cx);
                }
            }))
            .on_action(
                cx.listener(|this, _: &PreviousRow, window, cx| this.step_rows(-1, window, cx)),
            )
            .on_action(cx.listener(|this, _: &NextRow, window, cx| this.step_rows(1, window, cx)))
            .on_action(cx.listener(|this, _: &ToggleStory, window, cx| this.enter_row(window, cx)))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &ToggleProposal, _, cx| this.toggle_proposal(&name, cx)
            }))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &MoveStoryUp, window, cx| {
                    this.shift_story(&name, true, cx);
                    this.focus_row(&name, window, cx);
                }
            }))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &MoveStoryDown, window, cx| {
                    this.shift_story(&name, false, cx);
                    this.focus_row(&name, window, cx);
                }
            }))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &SendStory, window, cx| this.send_story(&name, window, cx)
            }))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &PickMode, _, cx| this.open_mode_menu(&name, cx)
            }))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &DeleteStory, _, cx| this.ask_delete(&name, cx)
            }))
            .when(!proposal, |row| {
                row.on_drag(drag, |drag, _, _, cx| cx.new(|_| drag.clone()))
                    .on_drag_move({
                        let gap = self.gap.clone();
                        move |event: &DragMoveEvent<StoryDrag>, window, _| {
                            let bounds = event.bounds;
                            if !bounds.contains(&event.event.position) {
                                return;
                            }
                            let at = ix + (event.event.position.y > bounds.center().y) as usize;
                            if gap.get() != Some((section, at)) {
                                gap.set(Some((section, at)));
                                window.refresh();
                            }
                        }
                    })
                    .on_drop(cx.listener(move |this, drag: &StoryDrag, _, cx| {
                        let at = this.gap.take().map_or(ix, |(_, at)| at);
                        this.move_story(&drag.name, section, at, cx);
                    }))
            })
            .when(dragging && gap == Some((section, ix)), |row| {
                row.child(crate::prompt_mode::drop_indicator(false, false, cx))
            })
            .when(
                dragging && gap == Some((section, ix + 1)) && ix + 1 == len,
                |row| row.child(crate::prompt_mode::drop_indicator(false, true, cx)),
            )
            // The grip, or a proposal's checkbox, in its column.
            .child(
                own_clicks(div().w(GRIP_WIDTH).flex_none().flex().justify_center())
                    .when_some(checkbox, |column, checkbox| column.child(checkbox))
                    .when(!proposal, |column| {
                        column.child(
                            Icon::new(IconName::GripVertical)
                                .xsmall()
                                .text_color(muted)
                                .cursor_grab(),
                        )
                    }),
            )
            // The mode pill, in its column, taking its own clicks.
            .child(
                own_clicks(div().relative().w(PILL_WIDTH).flex_none())
                    .child(mode_picker)
                    .children(mode_menu),
            )
            .child(
                h_flex()
                    .flex_1()
                    .min_w_0()
                    .gap_2()
                    .items_center()
                    .when(draft, |title| {
                        title.child(
                            div()
                                .flex_none()
                                .size(px(6.))
                                .rounded_full()
                                .bg(theme.primary),
                        )
                    })
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .truncate()
                            .text_sm()
                            .text_color(if untitled { muted } else { theme.foreground })
                            .child(title),
                    )
                    .when(attached, |title| {
                        title.child(Icon::new(IconName::Paperclip).xsmall().text_color(muted))
                    }),
            )
            // The status and time, right-aligned in a column of their own;
            // nothing for a story not yet sent.
            .child(
                div()
                    .w(STATUS_WIDTH)
                    .flex_none()
                    .flex()
                    .justify_end()
                    .children(status.map(|(state, elapsed)| status_label(state, elapsed, cx))),
            )
            .children(confirm.map(|confirm| own_clicks(div().flex_none()).child(confirm)))
            .children(resume.map(|resume| own_clicks(div().flex_none()).child(resume)))
            .when(!confirming, |row| {
                row.child(
                    own_clicks(h_flex())
                        .flex_none()
                        .gap_0p5()
                        .when(!focused, |buttons| {
                            buttons.invisible().group_hover(group, |this| this.visible())
                        })
                        .when(!matches!(section, Section::Done | Section::Proposed), |this| {
                            this.child(send)
                        })
                        .child(menu),
                )
            });
        gpui_kit::TestSupportExt::test_support(row).into_any_element()
    }

    fn render_open(&self, name: &str, window: &mut Window, cx: &mut Context<Self>) -> AnyElement {
        let (Some(story), Some(open)) = (self.story(name), self.open.as_ref()) else {
            return div().into_any_element();
        };
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let name = story.name.clone();
        let agent = crate::agent::of_project(Some(&self.project_dir));
        let (height, _) = open.fit.heights(&open.prompt, window, cx);
        let prompt = div()
            .relative()
            .w_full()
            .child(Editor::new(&open.prompt).h(height))
            .child(GrowToFit::tracker(
                &open.prompt,
                cx.entity().downgrade(),
                |this: &mut Self| &mut this.open.as_mut().expect("a story is open").fit,
            ))
            .child(open.completion.clone());
        let attachments = {
            let mut items: Vec<(String, usize, u8)> = Vec::new();
            for (ix, text) in story.anchor.attached_text.iter().enumerate() {
                let first = text.lines().next().unwrap_or_default();
                items.push((format!("Text: {first}"), ix, 0));
            }
            for (ix, path) in story.anchor.attached_images.iter().enumerate() {
                items.push((file_name(path), ix, 1));
            }
            for (ix, path) in story.anchor.attached_files.iter().enumerate() {
                items.push((file_name(path), ix, 2));
            }
            h_flex()
                .flex_wrap()
                .gap_1()
                .children(items.into_iter().map(|(label, ix, kind)| {
                    let name = name.clone();
                    h_flex()
                        .gap_1()
                        .pl_2()
                        .rounded(px(4.))
                        .bg(theme.secondary)
                        .text_xs()
                        .child(Icon::new(IconName::Paperclip).xsmall().text_color(muted))
                        .child(div().max_w(px(220.)).truncate().child(label.clone()))
                        .child(
                            Button::new(SharedString::from(format!(
                                "planning-detach-{name}-{kind}-{ix}"
                            )))
                            .ghost()
                            .xsmall()
                            .icon(IconName::X)
                            .tooltip(format!("Remove {label}"))
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.change(
                                    &name,
                                    |anchor| match kind {
                                        0 => {
                                            anchor.attached_text.remove(ix);
                                        }
                                        1 => {
                                            anchor.attached_images.remove(ix);
                                        }
                                        _ => {
                                            anchor.attached_files.remove(ix);
                                        }
                                    },
                                    cx,
                                )
                            })),
                        )
                }))
                .child({
                    let name = name.clone();
                    Button::new(SharedString::from(format!("planning-attach-{name}")))
                        .ghost()
                        .xsmall()
                        .icon(IconName::Paperclip)
                        .label("Attach")
                        .tooltip("Attach files to this story")
                        .on_click(
                            cx.listener(move |this, _, window, cx| this.attach(&name, window, cx)),
                        )
                })
        };
        // Its parameters, as the chat input shows them.
        let this = cx.entity().downgrade();
        let model = story.anchor.model.clone();
        let model_picker = {
            let (this, name) = (this.clone(), name.clone());
            Button::new(SharedString::from(format!("planning-model-{name}")))
                .ghost()
                .xsmall()
                .label(crate::models::label(agent, model.as_deref()))
                .tooltip("The model it is sent to")
                .dropdown_menu_with_anchor(gpui_kit::Anchor::TopLeft, move |mut menu, _, _| {
                    let choices = std::iter::once((None, "Default".to_string())).chain(
                        crate::models::available(agent)
                            .into_iter()
                            .map(|model| (Some(model.id), model.label)),
                    );
                    for (id, label) in choices {
                        let (this, name) = (this.clone(), name.clone());
                        let checked = id == model;
                        menu = menu.item(PopupMenuItem::new(label).checked(checked).on_click(
                            move |_, _, cx| {
                                let id = id.clone();
                                this.update(cx, |this, cx| {
                                    this.change(&name, |anchor| anchor.model = id, cx)
                                })
                                .ok();
                            },
                        ));
                    }
                    menu
                })
        };
        let efforts = crate::effort::available(agent);
        let effort = story.anchor.effort.clone();
        let effort_picker = (!efforts.is_empty()).then(|| {
            let (this, name) = (this.clone(), name.clone());
            Button::new(SharedString::from(format!("planning-effort-{name}")))
                .ghost()
                .xsmall()
                .label(crate::effort::label(agent, effort.as_deref()))
                .tooltip("The reasoning effort it is sent with")
                .dropdown_menu_with_anchor(gpui_kit::Anchor::TopLeft, move |mut menu, _, _| {
                    let choices = std::iter::once((None, "Default".to_string())).chain(
                        efforts
                            .iter()
                            .map(|effort| (Some(effort.id.clone()), effort.label.clone())),
                    );
                    for (id, label) in choices {
                        let (this, name) = (this.clone(), name.clone());
                        let checked = id == effort;
                        menu = menu.item(PopupMenuItem::new(label).checked(checked).on_click(
                            move |_, _, cx| {
                                let id = id.clone();
                                this.update(cx, |this, cx| {
                                    this.change(&name, |anchor| anchor.effort = id, cx)
                                })
                                .ok();
                            },
                        ));
                    }
                    menu
                })
        });
        let sliced = story.anchor.sliced;
        let slice = {
            let name = name.clone();
            Button::new(SharedString::from(format!("planning-slice-{name}")))
                .ghost()
                .xsmall()
                .when(sliced, |button| button.icon(IconName::Check))
                .label("Slice")
                .tooltip("Send the slice of each spec it references, rather than links to them")
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.change(&name, |anchor| anchor.sliced = !anchor.sliced, cx)
                }))
        };
        let label = |text: &'static str| div().text_xs().text_color(muted).child(text);
        let editor = v_flex()
            .id(SharedString::from(format!("planning-open-{name}")))
            .w_full()
            .gap_2()
            .p_3()
            .rounded(theme.radius)
            .bg(crate::theme::color(crate::theme::palette(cx).raised))
            .child(label("Title"))
            .child(Input::new(&open.title))
            .child(label("Prompt"))
            .child(prompt)
            .child(attachments)
            .child(
                h_flex()
                    .gap_1()
                    .items_center()
                    .child(model_picker)
                    .children(effort_picker)
                    .child(slice),
            );
        gpui_kit::TestSupportExt::test_support(editor).into_any_element()
    }

    /// The drafting panel beneath the Backlog's heading: the request, the
    /// run while it goes, its error, and the stories it proposed.
    fn render_draft_panel(&mut self, window: &mut Window, cx: &mut Context<Self>) -> AnyElement {
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let proposals = self.sections[3].len();
        let checked = self.sections[3].iter().filter(|story| story.checked).count();
        let Some(drafting) = &self.drafting else {
            return div().into_any_element();
        };
        let running = drafting.running;
        let error = drafting.error.clone();
        let details_open = drafting.details_open;
        let proposed_nothing = drafting.proposed_nothing;
        let input = drafting.input.clone();
        let mut panel = v_flex()
            .id("planning-draft-panel")
            .w_full()
            .gap_2()
            .p_3()
            .mb(HEADING_GAP)
            .rounded(theme.radius)
            .bg(crate::theme::color(crate::theme::palette(cx).raised))
            .child(
                div()
                    .text_xs()
                    .font_medium()
                    .child("Describe what you want"),
            )
            .child(Textarea::new(&input).disabled(running.is_some()))
            .child(
                h_flex().gap_1().justify_end().child(
                    Button::new("planning-draft-run")
                        .primary()
                        .small()
                        .icon(IconName::Sparkles)
                        .label(if proposals > 0 { "Draft more" } else { "Draft" })
                        .disabled(running.is_some())
                        .tooltip(format!("Have the harness propose stories ({MOD}Enter)"))
                        .on_click(cx.listener(|this, _, _, cx| this.draft(cx))),
                ),
            );
        // Loading: what the run is doing, where the proposals will appear.
        if let Some(started) = running {
            let elapsed = crate::subagents::format_elapsed(started.elapsed());
            panel = panel.child(
                h_flex()
                    .id("planning-draft-running")
                    .gap_2()
                    .items_center()
                    .child(
                        loading_line(
                            format!("Asking the harness to break it into stories… {elapsed}"),
                            muted,
                        )
                        .flex_1(),
                    )
                    .child(
                        Button::new("planning-draft-stop")
                            .ghost()
                            .small()
                            .icon(IconName::Square)
                            .label("Stop")
                            .tooltip("Stop drafting, proposing nothing")
                            .on_click(cx.listener(|this, _, _, cx| this.stop_draft(cx))),
                    ),
            );
            self.keep_ticking(cx);
        }
        // Error: what went wrong, in plain words, its details collapsed.
        if let Some(error) = error {
            panel = panel.child(
                v_flex()
                    .id("planning-draft-error")
                    .gap_1()
                    .child(
                        h_flex()
                            .gap_2()
                            .items_center()
                            .child(
                                div()
                                    .flex_1()
                                    .text_sm()
                                    .text_color(theme.danger)
                                    .child("The harness couldn't draft stories from that."),
                            )
                            .child(
                                Button::new("planning-draft-details")
                                    .ghost()
                                    .xsmall()
                                    .icon(if details_open {
                                        IconName::ChevronDown
                                    } else {
                                        IconName::ChevronRight
                                    })
                                    .label("Details")
                                    .tooltip(if details_open {
                                        "Hide what was reported"
                                    } else {
                                        "Show what was reported"
                                    })
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        if let Some(drafting) = &mut this.drafting {
                                            drafting.details_open = !drafting.details_open;
                                        }
                                        cx.notify();
                                    })),
                            )
                            .child(
                                Button::new("planning-draft-retry")
                                    .ghost()
                                    .xsmall()
                                    .label("Try again")
                                    .tooltip("Ask the harness again with the same request")
                                    .on_click(cx.listener(|this, _, _, cx| this.draft(cx))),
                            ),
                    )
                    .when(details_open, |details| {
                        details.child(
                            div()
                                .text_xs()
                                .text_color(muted)
                                .font_family(theme.mono_font_family.clone())
                                .child(error.trim().to_string()),
                        )
                    }),
            );
        }
        if proposed_nothing && proposals == 0 {
            panel = panel.child(empty_line(Section::Proposed.empty(), muted));
        }
        // The proposals, each a row as a story's, ticked to be added.
        if proposals > 0 {
            let gap = self.gap.get();
            let mut list = v_flex().w_full().gap(ROW_GAP).child(
                div()
                    .text_xs()
                    .text_color(muted)
                    .child(Section::Proposed.label()),
            );
            for ix in 0..proposals {
                let name = self.sections[3][ix].name.clone();
                let open = self.open.as_ref().is_some_and(|open| open.name == name);
                list = list.child(self.render_row(Section::Proposed, ix, open, gap, window, cx));
                if open {
                    list = list.child(self.render_open(&name, window, cx));
                }
            }
            panel = panel.child(list).child(
                h_flex()
                    .gap_1()
                    .justify_end()
                    .child(
                        Button::new("planning-discard-proposals")
                            .ghost()
                            .small()
                            .label("Discard")
                            .tooltip("Let every proposed story go")
                            .on_click(cx.listener(|this, _, window, cx| {
                                this.discard_proposals(window, cx)
                            })),
                    )
                    .child(
                        Button::new("planning-add-proposals")
                            .primary()
                            .small()
                            .label(match checked {
                                1 => "Add 1 story".to_string(),
                                n => format!("Add {n} stories"),
                            })
                            .disabled(checked == 0)
                            .tooltip("Add the ticked stories to the Backlog, in order")
                            .on_click(
                                cx.listener(|this, _, window, cx| this.add_proposals(window, cx)),
                            ),
                    ),
            );
        }
        gpui_kit::TestSupportExt::test_support(panel).into_any_element()
    }
}

fn file_name(path: &str) -> String {
    Path::new(path).file_name().map_or_else(
        || path.to_string(),
        |name| name.to_string_lossy().into_owned(),
    )
}

impl Render for Planning {
    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        if !cx.has_active_drag() {
            self.gap.set(None);
        }
        if let Some(open) = &mut self.open {
            open.fit.keep_cursor_in_view(&open.prompt, window, cx);
        }
        if self.any_running(cx) {
            self.keep_ticking(cx);
        }
        let next = self.render_section(Section::Next, window, cx);
        let backlog = self.render_section(Section::Backlog, window, cx);
        let done = (!self.sections[2].is_empty())
            .then(|| self.render_section(Section::Done, window, cx));
        // 24 pixels between sections, and around the column's top and sides.
        let column = v_flex()
            .w_full()
            .max_w(COLUMN_WIDTH)
            .gap_6()
            .pt_6()
            .px_6()
            .pb_6()
            .child(next)
            .child(backlog)
            .children(done);
        let planning = div()
            .id("planning")
            .key_context(CONTEXT)
            .track_focus(&self.focus)
            .size_full()
            .overflow_y_scroll()
            .bg(cx.theme().background)
            .on_action(
                cx.listener(|this, _: &NewStory, window, cx| this.new_story_here(window, cx)),
            )
            .on_action(
                cx.listener(|this, _: &SendSprint, window, cx| this.send_sprint(window, cx)),
            )
            .capture_action(cx.listener(|this, _: &Escape, window, cx| {
                if this.escape(window, cx) {
                    cx.stop_propagation();
                }
            }))
            .on_action(
                cx.listener(|this, _: &crate::main_window::Dismiss, window, cx| {
                    if !this.escape(window, cx) {
                        cx.propagate();
                    }
                }),
            )
            .capture_action(cx.listener(|this, action: &Enter, window, cx| {
                // Enter accepts an open completion rather than adding a line;
                // in the drafting panel, Ctrl/Cmd+Enter drafts.
                if let Some(open) = &this.open
                    && open.completion.read(cx).is_open()
                    && !action.secondary
                {
                    cx.stop_propagation();
                    open.completion
                        .update(cx, |menu, cx| menu.accept_selected(window, cx));
                } else if action.secondary && this.drafting.is_some() {
                    cx.stop_propagation();
                    this.draft(cx);
                }
            }))
            .capture_action(cx.listener(|this, _: &MoveUp, window, cx| {
                if let Some(open) = &this.open
                    && open.completion.read(cx).is_open()
                {
                    cx.stop_propagation();
                    open.completion
                        .update(cx, |menu, cx| menu.select_next(-1, window, cx));
                }
            }))
            .capture_action(cx.listener(|this, _: &MoveDown, window, cx| {
                if let Some(open) = &this.open
                    && open.completion.read(cx).is_open()
                {
                    cx.stop_propagation();
                    open.completion
                        .update(cx, |menu, cx| menu.select_next(1, window, cx));
                }
            }))
            .child(h_flex().w_full().justify_center().child(column));
        gpui_kit::TestSupportExt::test_support(planning)
    }
}

