use std::rc::Rc;

use gpui_kit::component::Root;
use gpui_kit::test::TestWindowExt as _;
use gpui_kit::{AnyWindowHandle, AppContext as _, Entity, TestAppContext};

use super::{Planning, PlanningHooks, Section};

fn hooks(draft: fn(&Path, &str) -> anyhow::Result<String>) -> PlanningHooks {
    PlanningHooks {
        state: Rc::new(|_, _| None),
        send: Rc::new(|_, _, _| {}),
        open_task: Rc::new(|_, _, _| {}),
        resume: Rc::new(|_, _, _| {}),
        draft,
        completions: Rc::new(crate::chat_input::prompt_completions),
    }
}

/// Planning, alone in a window, for the project at `dir`.
fn open_planning(
    dir: PathBuf,
    draft: fn(&Path, &str) -> anyhow::Result<String>,
    cx: &mut TestAppContext,
) -> (Entity<Planning>, AnyWindowHandle) {
    cx.update(|cx| {
        gpui_kit::init(cx);
        crate::piton_syntax::init();
        super::bind_keys(cx);
    });
    let mut planning = None;
    let window = cx.add_window(|window, cx| {
        let view = cx.new(|cx| Planning::new(dir, hooks(draft), cx));
        planning = Some(view.clone());
        Root::new(view, window, cx)
    });
    (planning.unwrap(), window.into())
}

/// A project whose Backlog holds stories titled `titles`, in order.
fn backlog(name: &str, titles: &[&str]) -> (PathBuf, Vec<String>) {
    let dir = project(name);
    let mut sections: [Vec<Story>; 4] = Default::default();
    for title in titles {
        let story = Story::new(title.to_string(), String::new(), SendMode::Both, &dir);
        save_story(&dir, &story.name, &story.anchor.source(&story.prompt)).unwrap();
        sections[1].push(story);
    }
    save_order_text(&dir, &order_of(&sections)).unwrap();
    let names = sections[1].iter().map(|story| story.name.clone()).collect();
    (dir, names)
}

fn titles(planning: &Entity<Planning>, section: Section, cx: &mut TestAppContext) -> Vec<String> {
    planning.read_with(cx, |planning, _| {
        planning
            .stories(section)
            .iter()
            .map(|story| story.title.clone())
            .collect()
    })
}

/// Empty, each section says what is missing and what to do.
#[gpui_kit::test]
async fn empty_sections_say_what_to_do(cx: &mut TestAppContext) {
    let dir = project("planning-empty-test");
    let (_, handle) = open_planning(dir.clone(), |_, _| anyhow::bail!("unused"), cx);
    cx.update_window(handle, |_, window, cx| {
        window.render_frame(cx);
        window.find("planning-empty-next");
        window.find("planning-empty-backlog");
    })
    .unwrap();
    std::fs::remove_dir_all(&dir).ok();
}

/// From the keyboard: Down moves to the next row, Alt+Up moves a story
/// up and on into Next sprint, M opens the mode picker, picked from with
/// the arrows and Enter, and Delete asks before Enter deletes.
#[gpui_kit::test]
async fn stories_are_worked_from_the_keyboard(cx: &mut TestAppContext) {
    let (dir, names) = backlog("planning-keys-test", &["One", "Two", "Three"]);
    let (planning, handle) = open_planning(dir.clone(), |_, _| anyhow::bail!("unused"), cx);
    let press = |key: &str, cx: &mut TestAppContext| {
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.press(key, cx);
            window.render_frame(cx);
        })
        .unwrap();
        cx.run_until_parked();
    };
    let focused = |cx: &mut TestAppContext| {
        cx.update_window(handle, |_, window, cx| planning.read(cx).focused_story(window))
            .unwrap()
    };
    cx.update_window(handle, |_, window, cx| {
        window.render_frame(cx);
        planning.update(cx, |planning, cx| planning.focus_row(&names[0], window, cx));
    })
    .unwrap();
    press("down", cx);
    assert_eq!(focused(cx).as_deref(), Some(names[1].as_str()));

    press("alt-up", cx);
    assert_eq!(titles(&planning, Section::Backlog, cx), ["Two", "One", "Three"]);
    press("alt-up", cx);
    assert_eq!(titles(&planning, Section::Next, cx), ["Two"]);
    assert_eq!(focused(cx).as_deref(), Some(names[1].as_str()));

    let mode = |cx: &mut TestAppContext| {
        planning.read_with(cx, |planning, _| planning.story(&names[1]).unwrap().mode())
    };
    let before = mode(cx);
    press("m", cx);
    cx.update_window(handle, |_, window, _| {
        window.find(SharedString::from(format!("planning-mode-menu-{}", names[1])));
    })
    .unwrap();
    press("down", cx);
    press("enter", cx);
    assert_ne!(mode(cx), before, "the mode picked wasn't set");
    assert!(planning.read_with(cx, |planning, _| planning.mode_menu.is_none()));

    press("delete", cx);
    cx.update_window(handle, |_, window, _| {
        window.find(SharedString::from(format!("planning-delete-{}", names[1])));
    })
    .unwrap();
    assert_eq!(titles(&planning, Section::Next, cx), ["Two"], "deleted unasked");
    press("enter", cx);
    assert!(titles(&planning, Section::Next, cx).is_empty());
    std::fs::remove_dir_all(&dir).ok();
}

fn two_stories(_: &Path, _: &str) -> anyhow::Result<String> {
    Ok(r#"{"stories": [
        {"title": "First", "prompt": "Do the first", "mode": "code"},
        {"title": "Second", "prompt": "Do the second", "mode": "chain"}
    ]}"#
        .into())
}

/// Drafting proposes stories in its panel, each ticked; they are kept
/// with the project until added, and adding moves only those ticked
/// into the Backlog, closing the panel.
#[gpui_kit::test]
async fn drafted_stories_are_proposed_then_added(cx: &mut TestAppContext) {
    let dir = project("planning-propose-test");
    let (planning, handle) = open_planning(dir.clone(), two_stories, cx);
    cx.update_window(handle, |_, window, cx| {
        planning.update(cx, |planning, cx| {
            planning.open_draft_panel(true, window, cx);
            let input = planning.drafting.as_ref().unwrap().input.clone();
            input.update(cx, |input, cx| input.set_value("Two things", window, cx));
            planning.draft(cx);
        });
    })
    .unwrap();
    cx.run_until_parked();
    assert_eq!(titles(&planning, Section::Proposed, cx), ["First", "Second"]);
    cx.update_window(handle, |_, window, cx| {
        window.render_frame(cx);
        window.find("planning-add-proposals");
    })
    .unwrap();
    // Kept with the project, ticked, until added.
    let saved = load(&dir);
    assert_eq!(saved[3].len(), 2);
    assert!(saved[3].iter().all(|story| story.checked));

    let first = planning.read_with(cx, |planning, _| planning.stories(Section::Proposed)[0].name.clone());
    cx.update_window(handle, |_, window, cx| {
        planning.update(cx, |planning, cx| {
            planning.toggle_proposal(&first, cx);
            planning.add_proposals(window, cx);
        });
    })
    .unwrap();
    cx.run_until_parked();
    assert_eq!(titles(&planning, Section::Backlog, cx), ["Second"]);
    assert!(titles(&planning, Section::Proposed, cx).is_empty());
    assert!(planning.read_with(cx, |planning, _| planning.drafting.is_none()));
    std::fs::remove_dir_all(&dir).ok();
}

/// A run that fails says so, with Try again, and keeps the request.
#[gpui_kit::test]
async fn a_failed_draft_says_why_and_keeps_the_request(cx: &mut TestAppContext) {
    let dir = project("planning-draft-error-test");
    let (planning, handle) =
        open_planning(dir.clone(), |_, _| anyhow::bail!("the harness isn't signed in"), cx);
    cx.update_window(handle, |_, window, cx| {
        planning.update(cx, |planning, cx| {
            planning.open_draft_panel(true, window, cx);
            let input = planning.drafting.as_ref().unwrap().input.clone();
            input.update(cx, |input, cx| input.set_value("Something", window, cx));
            planning.draft(cx);
        });
    })
    .unwrap();
    cx.run_until_parked();
    cx.update_window(handle, |_, window, cx| {
        window.render_frame(cx);
        window.find("planning-draft-error");
        window.find("planning-draft-retry");
        let drafting = planning.read(cx).drafting.as_ref().unwrap();
        assert_eq!(drafting.input.read(cx).value().as_ref(), "Something");
        assert!(drafting.error.as_deref().unwrap().contains("signed in"));
    })
    .unwrap();
    std::fs::remove_dir_all(&dir).ok();
}

