    assert_eq!(titles(&planning, Section::Backlog, cx), ["Two", "One", "Three"]);
    press("alt-up", cx);
    assert_eq!(titles(&planning, Section::Next, cx), ["Two"]);
    assert_eq!(focused(cx).as_deref(), Some(names[1].as_str()));

    let mode = |cx: &mut TestAppContext| {
        planning.read_with(cx, |planning, _| planning.story(&names[1]).unwrap().mode())
    };
    let before = mode(cx);
    press("m", cx);
    cx.update_window(handle, |_, window, _| {
        window.find(SharedString::from(format!("planning-mode-menu-{}", names[1])));
    })
    .unwrap();
    press("down", cx);
    press("enter", cx);
    assert_ne!(mode(cx), before, "the mode picked wasn't set");
    assert!(planning.read_with(cx, |planning, _| planning.mode_menu.is_none()));

    press("delete", cx);
    cx.update_window(handle, |_, window, _| {
        window.find(SharedString::from(format!("planning-delete-{}", names[1])));
    })
    .unwrap();
    assert_eq!(titles(&planning, Section::Next, cx), ["Two"], "deleted unasked");
    press("enter", cx);
    assert!(titles(&planning, Section::Next, cx).is_empty());
    std::fs::remove_dir_all(&dir).ok();
}

fn two_stories(_: &Path, _: &str) -> anyhow::Result<String> {
    Ok(r#"{"stories": [
        {"title": "First", "prompt": "Do the first", "mode": "code"},
        {"title": "Second", "prompt": "Do the second", "mode": "chain"}
    ]}"#
        .into())
}

/// Drafting proposes stories in its panel, each ticked; they are kept
/// with the project until added, and adding moves only those ticked
/// into the Backlog, closing the panel.
#[gpui_kit::test]
async fn drafted_stories_are_proposed_then_added(cx: &mut TestAppContext) {
    let dir = project("planning-propose-test");
    let (planning, handle) = open_planning(dir.clone(), two_stories, cx);
    cx.update_window(handle, |_, window, cx| {
        planning.update(cx, |planning, cx| {
            planning.open_draft_panel(true, window, cx);
            let input = planning.drafting.as_ref().unwrap().input.clone();
            input.update(cx, |input, cx| input.set_value("Two things", window, cx));
            planning.draft(cx);
        });
    })
    .unwrap();
    cx.run_until_parked();
    assert_eq!(titles(&planning, Section::Proposed, cx), ["First", "Second"]);
    cx.update_window(handle, |_, window, cx| {
        window.render_frame(cx);
        window.find("planning-add-proposals");
    })
    .unwrap();
    // Kept with the project, ticked, until added.
    let saved = load(&dir);
    assert_eq!(saved[3].len(), 2);
    assert!(saved[3].iter().all(|story| story.checked));

    let first = planning.read_with(cx, |planning, _| planning.stories(Section::Proposed)[0].name.clone());
    cx.update_window(handle, |_, window, cx| {
        planning.update(cx, |planning, cx| {
            planning.toggle_proposal(&first, cx);
            planning.add_proposals(window, cx);
        });
    })
    .unwrap();
    cx.run_until_parked();
    assert_eq!(titles(&planning, Section::Backlog, cx), ["Second"]);
    assert!(titles(&planning, Section::Proposed, cx).is_empty());
    assert!(planning.read_with(cx, |planning, _| planning.drafting.is_none()));
    std::fs::remove_dir_all(&dir).ok();
}

/// A run that fails says so, with Try again, and keeps the request.
#[gpui_kit::test]
async fn a_failed_draft_says_why_and_keeps_the_request(cx: &mut TestAppContext) {
    let dir = project("planning-draft-error-test");
    let (planning, handle) =
        open_planning(dir.clone(), |_, _| anyhow::bail!("the harness isn't signed in"), cx);
    cx.update_window(handle, |_, window, cx| {
        planning.update(cx, |planning, cx| {
            planning.open_draft_panel(true, window, cx);
            let input = planning.drafting.as_ref().unwrap().input.clone();
            input.update(cx, |input, cx| input.set_value("Something", window, cx));
            planning.draft(cx);
        });
    })
    .unwrap();
    cx.run_until_parked();
    cx.update_window(handle, |_, window, cx| {
        window.render_frame(cx);
        window.find("planning-draft-error");
        window.find("planning-draft-retry");
        let drafting = planning.read(cx).drafting.as_ref().unwrap();
        assert_eq!(drafting.input.read(cx).value().as_ref(), "Something");
        assert!(drafting.error.as_deref().unwrap().contains("signed in"));
    })
    .unwrap();
    std::fs::remove_dir_all(&dir).ok();
}

